WITH filtered_departments AS (SELECT *, ROUND(budget, 0) AS budget_rounded FROM departments WHERE budget <= 2734000 AND (budget >= 3661000 OR budget BETWEEN 1572000 AND 4005000)), summary AS (SELECT location, CASE WHEN budget >= 4291000 THEN 'high' WHEN budget >= 1153000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(*) AS num_departments FROM filtered_departments GROUP BY location, CASE WHEN budget >= 4291000 THEN 'high' WHEN budget >= 1153000 THEN 'mid' ELSE 'low' END) SELECT location, budget_bucket, num_departments FROM summary ORDER BY budget_bucket, location LIMIT 5;
